/* 100k holes, then free all 200k remaining blocks in random order under best fit (4000 mallocs)
 * Phase 1: 306000 mallocs under FIRST_FIT; phase 2: free every block i with i % MOD == REM
 * (plus i % MOD == REM2 with probability EXTRA_PM/1000) -> at least 100,000 free blocks;
 * phase 3 under BEST_FIT: free every remaining block in random order, one malloc (n in 1..300) after every 50 frees; then heap dump + leak report.
 * Generated by gen/perf_tests.py; expected output from the Python reference model. */
#include <stdio.h>
#include <string.h>
#include <stdint.h>
#include "myalloc.h"

#ifndef NBUILD
#define NBUILD 306000
#endif
#ifndef NOPS
#define NOPS 0
#endif
#define SEED 23ull
#define BUILD_POLICY FIRST_FIT
#define OPS_POLICY BEST_FIT
#define MINB 1
#define SPANB 100
#define MOD 3
#define REM 0
#define REM2 0
#define EXTRA_PM 0
#define MODE 1
#define PM 0
#define MEVERY 50
#define MINO 1
#define SPANO 300

#define NMAX (NBUILD + NOPS + NBUILD / MEVERY + 16)
static void *P[NMAX];
static int LIVE[NMAX];
static int NL;
static uint64_t S = SEED;

static uint64_t rnd(void)
{
    S ^= S << 13;
    S ^= S >> 7;
    S ^= S << 17;
    return S;
}

int main(void)
{
    int nid = 0;
    my_set_policy(BUILD_POLICY);
    for (int i = 0; i < NBUILD; i++) {
        size_t n = MINB + rnd() % SPANB;
        P[nid] = my_malloc(n);
        ((unsigned char *)P[nid])[0] = 1;
        nid++;
    }
    for (int i = 0; i < NBUILD; i++) {
        int fr = (i % MOD == REM) || (EXTRA_PM && i % MOD == REM2 && (int)(rnd() % 1000) < EXTRA_PM);
        if (fr)
            my_free(P[i]);
        else
            LIVE[NL++] = i;
    }
    my_set_policy(OPS_POLICY);
    if (MODE == 0) {
        for (int k = 0; k < NOPS; k++) {
            if (NL == 0 || (int)(rnd() % 1000) < PM) {
                size_t n = MINO + rnd() % SPANO;
                P[nid] = my_malloc(n);
                LIVE[NL++] = nid++;
            } else {
                int j = (int)(rnd() % (uint64_t)NL);
                int id = LIVE[j];
                LIVE[j] = LIVE[--NL];
                my_free(P[id]);
            }
        }
    } else {
        int cnt = 0;
        while (NL > 0) {
            int j = (int)(rnd() % (uint64_t)NL);
            int id = LIVE[j];
            LIVE[j] = LIVE[--NL];
            my_free(P[id]);
            if (++cnt % MEVERY == 0) {
                size_t n = MINO + rnd() % SPANO;
                P[nid++] = my_malloc(n);
            }
        }
    }
    my_heap_dump();
    my_leak_report();
    return 0;
}
